package ui;
import javafx.geometry.*; import javafx.scene.Node; import javafx.scene.control.*; import javafx.scene.image.Image; import javafx.scene.image.ImageView; import javafx.scene.layout.*; import service.*; import java.util.*; import java.util.prefs.Preferences;
/** Persistent desktop shell; each page receives the existing service instances. */
public class MainLayout extends BorderPane {
 private final BookService books; private final MemberService members; private final BorrowService borrows; private final Runnable onLogout; private final BorderPane page=new BorderPane(); private final VBox sidebar=new VBox(7); private final Label pageTitle=new Label(),pageSubtitle=new Label(); private final Map<String,Button> nav=new LinkedHashMap<>(); private boolean collapsed; private final Preferences preferences=Preferences.userNodeForPackage(MainLayout.class);
 public MainLayout(BookService books,MemberService members,BorrowService borrows,Runnable onLogout){this.books=books;this.members=members;this.borrows=borrows;this.onLogout=onLogout;getStyleClass().add("app-root");setLeft(sidebar());setTop(header());ImageView logo=new ImageView(new Image(getClass().getResourceAsStream("/images/tawsif-logo.jpeg")));logo.setFitWidth(50);logo.setPreserveRatio(true);logo.setSmooth(true);logo.setMouseTransparent(true);StackPane contentLayer=new StackPane(page,logo);StackPane.setAlignment(logo,Pos.BOTTOM_RIGHT);StackPane.setMargin(logo,new Insets(0,18,18,0));setCenter(contentLayer);if(preferences.getBoolean("darkTheme",false))getStyleClass().add("dark");navigate("Dashboard");}
 private Node header(){pageTitle.getStyleClass().add("header-title");pageSubtitle.getStyleClass().add("header-subtitle");VBox labels=new VBox(3,pageTitle,pageSubtitle);TextField search=new TextField();search.setPromptText("⌕   Search...");search.getStyleClass().add("header-search");Region gap=new Region();HBox.setHgrow(gap,Priority.ALWAYS);Button bell=new Button("♧"),theme=new Button(preferences.getBoolean("darkTheme",false)?"☾  Dark":"☼  Light");bell.getStyleClass().add("icon-button");bell.setTooltip(new Tooltip("Overdue loan notifications"));bell.setOnAction(e->showOverdueNotifications());theme.getStyleClass().add("icon-button");theme.setTooltip(new Tooltip("Toggle light/dark theme"));theme.setOnAction(e->{toggleTheme();theme.setText(getStyleClass().contains("dark")?"☾  Dark":"☼  Light");});Button avatar=new Button("LA");avatar.getStyleClass().add("avatar");avatar.setTooltip(new Tooltip("Account menu"));ContextMenu account=new ContextMenu();MenuItem logout=new MenuItem("Log out");logout.setOnAction(e->confirmLogout());account.getItems().add(logout);avatar.setOnAction(e->account.show(avatar,javafx.geometry.Side.BOTTOM,0,0));HBox h=new HBox(15,labels,gap,search,bell,theme,avatar);h.setAlignment(Pos.CENTER_LEFT);h.setPadding(new Insets(13,25,13,27));h.getStyleClass().add("top-header");return h;}
 private void confirmLogout(){Alert confirmation=new Alert(Alert.AlertType.CONFIRMATION,"Are you sure you want to log out?",new ButtonType("Yes, log out",ButtonType.YES.getButtonData()),ButtonType.CANCEL);confirmation.setTitle("Log out");confirmation.setHeaderText("End this session?");if(confirmation.showAndWait().orElse(ButtonType.CANCEL).getButtonData()==ButtonType.YES.getButtonData())onLogout.run();}
 private Node sidebar(){sidebar.getStyleClass().add("sidebar");sidebar.setPadding(new Insets(18,12,14,12));Label mark=new Label("▰");mark.getStyleClass().add("brand-mark");Label name=new Label("Smart Library");name.getStyleClass().add("brand-name");Label sub=new Label("Management System");sub.getStyleClass().add("brand-subtitle");VBox wordmark=new VBox(2,name,sub);wordmark.getStyleClass().add("wordmark");Button collapseButton=new Button("‹  Collapse");collapseButton.getStyleClass().add("collapse-button");collapseButton.setOnAction(e->collapse(!collapsed));Region gap=new Region();HBox.setHgrow(gap,Priority.ALWAYS);HBox brand=new HBox(10,mark,wordmark,gap,collapseButton);brand.setAlignment(Pos.CENTER_LEFT);brand.getStyleClass().add("brand");Label main=caption("MAIN"),other=caption("OTHER");addNav("Dashboard","⌂");addNav("Books","▣");addNav("Members","♙");addNav("Borrow & Return","⇄");addNav("Borrow Records","◴");addNav("Settings","⚙");Region push=new Region();VBox.setVgrow(push,Priority.ALWAYS);Label icon=new Label("LA");icon.getStyleClass().add("admin-icon");VBox adminText=new VBox(new Label("Library Admin"),new Label("Administrator"));adminText.getStyleClass().add("admin-text");HBox admin=new HBox(10,icon,adminText);admin.getStyleClass().add("admin-area");sidebar.getChildren().addAll(brand,main,nav.get("Dashboard"),nav.get("Books"),nav.get("Members"),nav.get("Borrow & Return"),nav.get("Borrow Records"),other,nav.get("Settings"),push,admin);return sidebar;}
 private Label caption(String s){Label l=new Label(s);l.getStyleClass().add("nav-caption");return l;} private void addNav(String title,String icon){Button b=new Button(icon+"  "+title);b.setUserData(new String[]{icon,title});b.setMaxWidth(Double.MAX_VALUE);b.getStyleClass().add("sidebar-item");b.setOnAction(e->navigate(title));nav.put(title,b);}
 private void navigate(String title){String sub;Node v;switch(title){case "Books"-> {sub="Manage your collection";v=new BookView(books,this::refresh);}case "Members"->{sub="Registered library members";v=new MemberView(members,this::refresh);}case "Borrow & Return"->{sub="Lending workflow";v=new BorrowView(books,members,borrows,false,this::refresh);}case "Borrow Records"->{sub="Complete transaction history";v=new BorrowRecordView(books,members,borrows);}case "Settings"->{sub="System configuration";v=new SettingsView(this::toggleTheme,()->getStyleClass().contains("dark"));}default->{title="Dashboard";sub="Library overview and activity";v=new DashboardView(books,members,borrows,()->navigate("Books"),()->navigate("Members"),()->navigate("Borrow & Return"));}}pageTitle.setText(title);pageSubtitle.setText(sub);page.setCenter(v);nav.values().forEach(b->b.getStyleClass().remove("sidebar-item-active"));nav.get(title).getStyleClass().add("sidebar-item-active");}
 private void showOverdueNotifications(){var overdue=borrows.getBorrowRecords().stream().filter(r->{if(r.isReturned())return false;try{return java.time.LocalDate.parse(r.getReturnDate()).isBefore(java.time.LocalDate.now());}catch(RuntimeException ex){return false;}}).toList();String message=overdue.isEmpty()?"There are no overdue loans.":overdue.size()+" overdue loan(s):\n"+overdue.stream().limit(8).map(r->{var b=books.searchBookById(r.getBookId());var m=members.searchMemberById(r.getMemberId());return "• "+(m==null?"Member #"+r.getMemberId():m.getName())+" — "+(b==null?"Book #"+r.getBookId():b.getTitle())+", due "+r.getReturnDate();}).collect(java.util.stream.Collectors.joining("\n"));Alert alert=new Alert(Alert.AlertType.INFORMATION,message,ButtonType.OK);alert.setTitle("Overdue loans");alert.setHeaderText("Library notifications");alert.showAndWait();} private void refresh(){navigate(pageTitle.getText());} private void collapse(boolean value){collapsed=value;if(value)sidebar.getStyleClass().add("sidebar-collapsed");else sidebar.getStyleClass().remove("sidebar-collapsed");nav.values().forEach(b->{String[]d=(String[])b.getUserData();b.setText(value?d[0]:d[0]+"  "+d[1]);b.setTooltip(value?new Tooltip(d[1]):null);});} private void toggleTheme(){boolean dark=getStyleClass().contains("dark");if(dark)getStyleClass().remove("dark");else getStyleClass().add("dark");preferences.putBoolean("darkTheme",!dark);}
}
